ee:message.ee:set-payload:
%dw 2.0
output application/json
var bodyText = ((payload.Body default payload.body default "") as String)
var lowerBody = lower(bodyText)
var mediaCount = ((payload.NumMedia default "0") as Number) default 0
var firstMediaType = ((payload.MediaContentType0 default "") as String)
var firstMediaKind =
    if (firstMediaType startsWith "audio/") "voice note"
    else if (firstMediaType startsWith "image/") "image"
    else if (firstMediaType == "application/pdf") "document"
    else if (mediaCount > 0) "media file"
    else "none"
fun hasAny(words) = sizeOf(words filter ((word) -> lowerBody contains word)) > 0
var categories = [
    if (hasAny(["wait", "queue", "delay"])) "WAIT_TIME" else null,
    if (hasAny(["room", "clean", "bed"])) "ROOM_READINESS" else null,
    if (hasAny(["bill", "invoice", "refund", "insurance", "payment"])) "BILLING" else null,
    if (hasAny(["pharmacy", "medicine late", "stock", "supply"])) "PHARMACY_STOCK" else null,
    if (hasAny(["lab", "test result"])) "LAB_VENDOR" else null,
    if (hasAny(["food", "meal"])) "FOOD_SERVICE" else null,
    if (hasAny(["rude", "staff"])) "STAFF_INTERACTION" else null,
    if (hasAny(["privacy", "unsafe"])) "PRIVACY_SAFETY" else null,
    if (hasAny(["diagnose", "dosage", "treatment", "triage", "chest pain", "emergency"])) "CLINICAL_REQUEST" else null,
    if (mediaCount > 0) "VOICE_OR_MEDIA" else null
] filter ($ != null)
var safeCategories = if (isEmpty(categories)) ["GENERAL_SERVICE"] else categories
var summaryParts = [
    if (safeCategories contains "WAIT_TIME") "waiting time" else null,
    if (safeCategories contains "ROOM_READINESS") "room readiness" else null,
    if (safeCategories contains "BILLING") "billing or payment" else null,
    if (safeCategories contains "PHARMACY_STOCK") "pharmacy or supply" else null,
    if (safeCategories contains "LAB_VENDOR") "lab response" else null,
    if (safeCategories contains "FOOD_SERVICE") "food service" else null,
    if (safeCategories contains "STAFF_INTERACTION") "staff interaction" else null,
    if (safeCategories contains "PRIVACY_SAFETY") "privacy or safety" else null,
    if (safeCategories contains "CLINICAL_REQUEST") "clinical review" else null,
    if (safeCategories contains "VOICE_OR_MEDIA") firstMediaKind else null
] filter ($ != null)
---
{
    tenantKey: p("northstar.tenant"),
    purpose: p("northstar.purpose"),
    messageSid: ((payload.MessageSid default payload.SmsSid default uuid()) as String),
    sourceChannel: "Twilio Sandbox WhatsApp",
    rawBody: bodyText,
    from: ((payload.From default "") as String),
    messageSummary:
        if (!isEmpty(bodyText)) "A WhatsApp message mentions " ++ (summaryParts joinBy ", ") ++ "."
        else if (mediaCount > 0) "A WhatsApp " ++ firstMediaKind ++ " was received and needs transcript or extraction before action."
        else "A WhatsApp message needs service review.",
    categories: safeCategories,
    mediaCount: mediaCount,
    firstMediaType: firstMediaType,
    firstMediaKind: firstMediaKind,
    mediaUrl0: ((payload.MediaUrl0 default "") as String),
    clinicalRequest: safeCategories contains "CLINICAL_REQUEST"
}

%dw 2.0
output application/xml
---
{
    Response: {
        Message: "Thanks. North Star received this. A manager will review it."
    }
}

%dw 2.0
output application/xml
---
{
    Response: {
        Message: "Thanks. North Star received this. A manager will review it."
    }
}

%dw 2.0
output application/json
var entry = ((payload.entry default [])[0] default {})
var change = ((entry.changes default [])[0] default {})
var value = change.value default {}
var message = ((value.messages default [])[0] default {})
var contact = ((value.contacts default [])[0] default {})
var messageType = ((message.type default "") as String)
var bodyText =
    if (messageType == "text") ((message.text.body default "") as String)
    else ""
var mediaCount = if (messageType in ["audio", "image", "document", "video"]) 1 else 0
var firstMediaType =
    if (messageType == "audio") ((message.audio.mime_type default "audio/unknown") as String)
    else if (messageType == "image") ((message.image.mime_type default "image/unknown") as String)
    else if (messageType == "document") ((message.document.mime_type default "application/octet-stream") as String)
    else if (messageType == "video") ((message.video.mime_type default "video/unknown") as String)
    else ""
var firstMediaKind =
    if (messageType == "audio") "voice note"
    else if (messageType == "image") "image"
    else if (messageType == "document") "document"
    else if (messageType == "video") "video"
    else "none"
var firstMediaId =
    if (messageType == "audio") ((message.audio.id default "") as String)
    else if (messageType == "image") ((message.image.id default "") as String)
    else if (messageType == "document") ((message.document.id default "") as String)
    else if (messageType == "video") ((message.video.id default "") as String)
    else ""
var lowerBody = lower(bodyText)
fun hasAny(words) = sizeOf(words filter ((word) -> lowerBody contains word)) > 0
var categories = [
    if (hasAny(["wait", "queue", "delay"])) "WAIT_TIME" else null,
    if (hasAny(["room", "clean", "bed"])) "ROOM_READINESS" else null,
    if (hasAny(["bill", "invoice", "refund", "insurance", "payment"])) "BILLING" else null,
    if (hasAny(["pharmacy", "medicine late", "stock", "supply"])) "PHARMACY_STOCK" else null,
    if (hasAny(["lab", "test result"])) "LAB_VENDOR" else null,
    if (hasAny(["food", "meal"])) "FOOD_SERVICE" else null,
    if (hasAny(["rude", "staff"])) "STAFF_INTERACTION" else null,
    if (hasAny(["privacy", "unsafe"])) "PRIVACY_SAFETY" else null,
    if (hasAny(["diagnose", "dosage", "treatment", "triage", "chest pain", "emergency"])) "CLINICAL_REQUEST" else null,
    if (mediaCount > 0) "VOICE_OR_MEDIA" else null
] filter ($ != null)
var safeCategories = if (isEmpty(categories)) ["GENERAL_SERVICE"] else categories
var summaryParts = [
    if (safeCategories contains "WAIT_TIME") "waiting time" else null,
    if (safeCategories contains "ROOM_READINESS") "room readiness" else null,
    if (safeCategories contains "BILLING") "billing or payment" else null,
    if (safeCategories contains "PHARMACY_STOCK") "pharmacy or supply" else null,
    if (safeCategories contains "LAB_VENDOR") "lab response" else null,
    if (safeCategories contains "FOOD_SERVICE") "food service" else null,
    if (safeCategories contains "STAFF_INTERACTION") "staff interaction" else null,
    if (safeCategories contains "PRIVACY_SAFETY") "privacy or safety" else null,
    if (safeCategories contains "CLINICAL_REQUEST") "clinical review" else null,
    if (safeCategories contains "VOICE_OR_MEDIA") firstMediaKind else null
] filter ($ != null)
---
{
    tenantKey: p("northstar.tenant"),
    purpose: p("northstar.purpose"),
    messageSid: ((message.id default uuid()) as String),
    sourceChannel: "Meta WhatsApp Cloud API",
    rawBody: bodyText,
    from: ((message.from default contact.wa_id default "") as String),
    messageSummary:
        if (!isEmpty(bodyText)) "A WhatsApp message mentions " ++ (summaryParts joinBy ", ") ++ "."
        else if (mediaCount > 0) "A WhatsApp " ++ firstMediaKind ++ " was received and needs transcript or extraction before action."
        else "A WhatsApp message needs service review.",
    categories: safeCategories,
    mediaCount: mediaCount,
    firstMediaType: firstMediaType,
    firstMediaKind: firstMediaKind,
    mediaUrl0: firstMediaId,
    clinicalRequest: safeCategories contains "CLINICAL_REQUEST"
}
